import random
from collections import Counter

def task_func(strings: list) -> dict:
    if not isinstance(strings, list):
        raise TypeError("strings must be a list")

    pattern = "pattern"
    counts = Counter()

    for s in strings:
        if not isinstance(s, str):
            continue
        counts[s] = s.count(pattern)

    return dict(counts)
